QuestGuidance.Register("en",1,{
[1]="70035204\n1\tFind and defeat Nágri\tNágri, the leader of the White Hand Orcs in the Writhendowns, can be found at Fushaum-dorám. You should find and defeat Nágri.\n2\tFind and defeat Nágri\tNágri, the leader of the White Hand Orcs in the Writhendowns, can be found at Fushaum-dorám. You should find and defeat Nágri.\n3\tCompleted\tYou have defeated Nágri, the leader of the White Hand Orcs at Fushaum-dorám. Hopefully this will hinder the plans of whatever new assault these Orcs were hatching.\n",
[2]="70059292\n1\tComplete 'Mission: The Further Adventures of Bilbo Baggins, Chapter 1'\tYour mission is to find Bilbo Baggins. Speak to Celeblír to begin your search!\n2\tTalk to Celeblír\tCeleblír is west of the Last Homely House, near the Town Crier.\n",
[3]="7006197E\n1\tTalk to Elladan outside of Elrond's Library\tElladan is waiting for you outside of Elrond's Library.\n2\tComplete 'Mission: The Further Adventures of Elladan & Elrohir, Chapter 1'\tYou should talk to Elladan outside of Elrond's Library to begin your search of the Bruinen.\n3\tTalk to Elrohir\tYour search of the Bruinen has taken you to Echad Candelleth. You should talk to Elrohir.\n",
[4]="70059293\n1\tComplete 'Mission: The Further Adventures of Bilbo Baggins, Chapter 2'\tYour mission is to find Bilbo Baggins. Speak to Celeblír to continue the search!\n2\tTalk to Celeblír\tCeleblír is west of the Last Homely House, near the Town Crier.\n",
[5]="70061985\n1\tComplete 'Mission: The Further Adventures of Elladan & Elrohir, Chapter 2'\tElrohir has sighted a Great Eagle flying towards Eregion. You should talk to Elrohir at Echad Candelleth in the Trollshaws to continue your journey.\n2\tTalk to Elladan\tYou and the twins have made it to Echad Eregion. Elladan has something to say to you.\n",
[6]="70059295\n1\tComplete 'Mission: The Further Adventures of Bilbo Baggins, Chapter 3'\tYour mission is to find Bilbo Baggins. Speak to Celeblír to continue the search!\n2\tTalk to Celeblír\tCeleblír is west of the Last Homely House, near the Town Crier.\n",
[7]="70061984\n1\tComplete 'Mission: The Further Adventures of Elladan & Elrohir, Chapter 3'\tThe twins' chosen route into Lórien crosses through the Redhorn Pass. You should talk to Elladan at Echad Eregion in Eregion to continue your journey.\n2\tTalk to Elrohir\tAfter the unnerving trek through the Redhorn Pass, your party has made it safely to the Dimrill Dale. You should talk to Elrohir to see how he's doing.\n",
[8]="70059294\n1\tComplete 'Mission: The Further Adventures of Bilbo Baggins, Chapter 4'\tYour mission is to find Bilbo Baggins. Speak to Celeblír to continue the search!\n2\tTalk to Celeblír\tCeleblír is west of the Last Homely House, near the Town Crier.\n",
[9]="70061983\n1\tComplete 'Mission: The Further Adventures of Elladan & Elrohir, Chapter 4'\tElrohir is worried about the news Gwaihir brought regarding the wolves along the Anduin. You should talk to Elrohir at Echad Andestel in Lothlórien to continue your journey.\n2\tTalk to Elladan\tYour party has discovered a possible Warg presence in Lothlórien. You should talk to Elladan to see what the twins plan to do next.\n",
[10]="70059296\n1\tComplete 'Mission: The Further Adventures of Bilbo Baggins, Chapter 5'\tYour mission is to find Bilbo Baggins. Speak to Celeblír to continue the search!\n2\tTalk to Celeblír\tCeleblír is west of the Last Homely House, near the Town Crier.\n",
[11]="7006198A\n1\tComplete 'Mission: The Further Adventures of Elladan & Elrohir, Chapter 5'\tGaladhrim scouts have sighted Wargs around the northern borders of Lórien. You should talk to Elladan outside of Caras Galadhon in Lothlórien to begin heading north.\n2\tTalk to Elrond\tWith the help of the Galadhrim and fresh supplies, your return to Rivendell has gone smoothly. Lord Elrond wishes to have a word with you.\n",
